#!/usr/bin/env bash
# ==============================================================================
# OzoneCast Studio - Synology DS720+ (DSM 7.2) One-Step Docker Installer
# ==============================================================================
set -e

TARGET_DIR="/volume1/docker/ozonecast"
echo "=========================================================="
echo " Deploying OzoneCast Studio to ${TARGET_DIR}"
echo "=========================================================="

mkdir -p "${TARGET_DIR}/data"
chmod -R 775 "${TARGET_DIR}"

echo "[1/3] Extracting application files..."
PAYLOAD=""
echo "${PAYLOAD}" | base64 -d | tar -xzf - -C "${TARGET_DIR}"
mkdir -p "${TARGET_DIR}/data"

cd "${TARGET_DIR}"
echo "[2/3] Building & starting Docker container on Synology DS720+..."
if docker compose version >/dev/null 2>&1; then
  docker compose up -d --build
elif command -v docker-compose >/dev/null 2>&1; then
  docker-compose up -d --build
else
  /var/packages/ContainerManager/target/usr/bin/docker compose up -d --build
fi

NAS_IP=$(hostname -I 2>/dev/null | awk '{print $1}')
echo "=========================================================="
echo " OzoneCast Studio is now running!"
echo " Open in browser: http://${NAS_IP:-<YOUR-NAS-IP>}:3080"
echo "=========================================================="
